={{ (() => {
  const b = $json.body;

  // L'image arrive soit par URL publique, soit en base64 — une pièce jointe
  // Discord derrière un jeton n'est pas récupérable par Anthropic.
  const brut = String(b.image_url || '');
  const dataUrl = brut.match(/^data:([^;]+);base64,(.*)$/);
  const source = dataUrl
    ? { type: 'base64', media_type: dataUrl[1], data: dataUrl[2] }
    : { type: 'url', url: brut };

  const criteres = Array.isArray(b.criteria) && b.criteria.length
    ? b.criteria
    : ['Texture', 'Couleur', 'Présentation', 'Respect de la recette'];

  // Le schéma est IMPOSÉ par un outil forcé, au lieu d'être demandé en prose.
  // L'ancienne version disait « Réponds UNIQUEMENT en JSON valide » puis
  // cherchait un bloc ```json dans le texte : quand le modèle enrobait sa
  // réponse, le JSON.parse échouait et l'apprenant recevait une erreur 500.
  const outil = {
    name: 'rendre_evaluation',
    description: 'Rend l évaluation structurée du plat photographié.',
    input_schema: {
      type: 'object',
      properties: {
        overall_score: { type: 'integer', minimum: 0, maximum: 100 },
        criteria: {
          type: 'array',
          items: {
            type: 'object',
            properties: {
              name: { type: 'string' },
              score: { type: 'integer', minimum: 0, maximum: 100 },
              comment: { type: 'string' }
            },
            required: ['name', 'score', 'comment']
          }
        },
        feedback: { type: 'string' },
        improvements: { type: 'array', items: { type: 'string' } },
        highlights: { type: 'array', items: { type: 'string' } }
      },
      required: ['overall_score', 'criteria', 'feedback', 'improvements', 'highlights']
    }
  };

  const consigne = [
    'Tu es un chef cuisinier expert qui évalue des plats cuisinés par des apprenants.',
    '',
    'Recette attendue : ' + (b.recipe_name || 'non spécifiée'),
    'Description : ' + (b.recipe_description || 'évalue selon les critères culinaires standards'),
    'Critères : ' + criteres.join(', '),
    '',
    'Note chaque critère sur 100. Le feedback doit être constructif et encourageant :',
    'il s adresse à un apprenant, pas à un jury. Signale ce qui est réussi avant ce',
    'qui peut progresser.'
  ].join('\n');

  return JSON.stringify({
    model: $env.LEARNING_VISION_MODEL || 'claude-sonnet-4-6',
    max_tokens: 2048,
    tools: [outil],
    tool_choice: { type: 'tool', name: 'rendre_evaluation' },
    messages: [{ role: 'user', content: [
      { type: 'image', source: source },
      { type: 'text', text: consigne }
    ] }]
  });
})() }}

