// Lecture du résultat de l'évaluation.
//
// Deux défauts corrigés ici :
//
// 1. L'échec d'appel était maquillé. Avec onError=continueRegularOutput, un 404
//    (modèle retiré) ou un 401 (clé) ne lève pas d'erreur : le nœud émet l'objet
//    d'erreur, `content[0].text` vaut '', le JSON.parse échoue, et l'apprenant
//    recevait « Failed to parse evaluation » en 500. La cause réelle était perdue.
// 2. Le JSON était cherché dans du texte. Le schéma est désormais imposé par un
//    outil forcé : la réponse arrive déjà structurée dans le bloc `tool_use`.
const webhook = $('Webhook').first().json;
const rep = $input.first().json;

// -- l'appel a-t-il abouti ? ------------------------------------------------
if (rep?.error !== undefined || rep?.content === undefined) {
  const brut = String(rep?.error?.message || rep?.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  const statut = m ? parseInt(m[1], 10) : 502;
  return [{ json: {
    success: false,
    submission_id: webhook.body?.submission_id ?? null,
    error: {
      code: statut,
      message: brut || "L'API du modèle n'a pas répondu",
      status: statut === 404 ? 'MODEL_NOT_FOUND' : (statut === 401 ? 'AUTH_FAILED' : 'PROVIDER_ERROR')
    }
  } }];
}

const bloc = (rep.content || []).find(c => c.type === 'tool_use');
if (!bloc || !bloc.input) {
  // Le modèle a répondu sans utiliser l'outil imposé — ne devrait pas arriver
  // avec tool_choice forcé, mais on ne suppose pas.
  return [{ json: {
    success: false,
    submission_id: webhook.body?.submission_id ?? null,
    error: {
      code: 502,
      message: "Le modèle n'a pas rendu d'évaluation structurée",
      status: 'UNSTRUCTURED_RESPONSE',
      stop_reason: rep.stop_reason ?? null
    }
  } }];
}

const e = bloc.input;
return [{ json: {
  success: true,
  submission_id: webhook.body.submission_id,
  guild_id: webhook.body.guild_id,
  modele_servi: rep.model ?? null,
  grade_payload: {
    feedback: e.feedback,
    grade: e.overall_score,
    graded_by: 'ai',
    ai_evaluation: {
      criteria: e.criteria,
      overall_comment: e.feedback,
      improvements: e.improvements,
      highlights: e.highlights
    }
  },
  evaluation: e
} }];

// Vérification de l'ENREGISTREMENT, puis réponse.
//
// Défaut corrigé : ce nœud lisait `apiResponse.id`, `.grade`, `.xp_earned` sans
// jamais vérifier que l'écriture avait eu lieu. `Save Grade` étant en
// onError=continueRegularOutput, un 401 ou un 500 de l'API produisait un objet
// d'erreur sans ces champs — et le workflow répondait `success: true` avec des
// valeurs `undefined`. Une note jamais enregistrée était annoncée enregistrée.
// Même famille qu'azy.daily#150.
const rep = $input.first().json;
const parse = $('Parse Evaluation').first().json;

let statut = rep?.statusCode;
if (statut === undefined) {
  const brut = String(rep?.error?.message || rep?.message || '');
  const m = brut.match(/(\d{3})\s*-\s*/);
  statut = m ? parseInt(m[1], 10) : ((rep?.error || rep?.code) ? 502 : 200);
}
const corps = rep?.body ?? rep;
const enregistre = statut < 400 && corps && corps.id !== undefined;

if (!enregistre) {
  return [{ json: {
    success: false,
    submission_id: parse.submission_id,
    // L'évaluation est rendue quand même : elle a coûté un appel au modèle et
    // reste utile à l'appelant, même si la note n'a pas été persistée.
    evaluation: parse.evaluation,
    error: {
      code: statut >= 400 ? statut : 502,
      message: "L'évaluation a réussi mais la note n'a pas été enregistrée",
      status: 'GRADE_NOT_SAVED'
    },
    meta: {
      workflow: 'learning-evaluate-photo',
      provider: 'anthropic',
      model: parse.modele_servi,
      timestamp: new Date().toISOString()
    }
  } }];
}

return [{ json: {
  success: true,
  data: {
    submission_id: corps.id,
    grade: corps.grade,
    feedback: corps.feedback,
    xp_earned: corps.xp_earned,
    evaluation: parse.evaluation
  },
  meta: {
    workflow: 'learning-evaluate-photo',
    provider: 'anthropic',
    // Le modèle réellement servi, plus une constante qui mentait dès qu'on
    // changeait le modèle en amont.
    model: parse.modele_servi,
    timestamp: new Date().toISOString()
  }
} }];

