parameters.jsCode:
const webhookData = $('Webhook').first().json;
const llmResponse = $input.first().json;

try {
  const content = llmResponse.content?.[0]?.text || '';

  // Find JSON in the response
  let jsonStr = content;
  const jsonMatch = content.match(/```json\n?([\s\S]*?)\n?```/);
  if (jsonMatch) {
    jsonStr = jsonMatch[1];
  }

  const evaluation = JSON.parse(jsonStr);

  // Build grade payload for API
  const gradePayload = {
    feedback: evaluation.feedback,
    grade: evaluation.overall_score,
    graded_by: 'ai',
    ai_evaluation: {
      criteria: evaluation.criteria,
      overall_comment: evaluation.feedback,
      improvements: evaluation.improvements,
      highlights: evaluation.highlights
    }
  };

  return {
    json: {
      success: true,
      submission_id: webhookData.body.submission_id,
      guild_id: webhookData.body.guild_id,
      grade_payload: gradePayload,
      evaluation: evaluation
    }
  };
} catch (e) {
  return {
    json: {
      success: false,
      error: {
        code: 500,
        message: 'Failed to parse evaluation: ' + e.message,
        raw_response: llmResponse.content?.[0]?.text?.substring(0, 500)
      }
    }
  };
}

const apiResponse = $input.first().json;
const parseData = $('Parse Evaluation').first().json;

return {
  json: {
    success: true,
    data: {
      submission_id: apiResponse.id,
      grade: apiResponse.grade,
      feedback: apiResponse.feedback,
      xp_earned: apiResponse.xp_earned,
      evaluation: parseData.evaluation
    },
    meta: {
      workflow: 'learning-evaluate-photo',
      provider: 'anthropic',
      model: 'claude-3-5-sonnet-20241022',
      timestamp: new Date().toISOString()
    }
  }
};
